Object.assign(SNIP,{"l43mau": "class MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) { p = new int[n]; }   // nhận tài nguyên trong hàm tạo\n    ~MangDong() { delete[] p; }                   // trả tài nguyên trong hàm hủy\n    int& operator[](int i) { return p[i]; }\n};\nvoid xuLy(int n) {\n    MangDong a(n);\n    if (n > 100) return;     // ra khỏi hàm ở đâu cũng được: ~MangDong() vẫn chạy\n    // ...\n}                            // a hết phạm vi: ~MangDong() chạy, vùng nhớ được trả", "l43ba": "class MangDong {\n    // ...\n    MangDong(const MangDong& o);              // 1. hàm tạo sao chép: tạo mảng MỚI rồi chép từng phần tử\n    MangDong& operator=(const MangDong& o);   // 2. toán tử gán: trả mảng cũ, tạo mảng mới, chép\n    ~MangDong();                              // 3. hàm hủy\n};\n// hoặc cấm hẳn việc chép:\n    MangDong(const MangDong&) = delete;\n    MangDong& operator=(const MangDong&) = delete;"});PRESET_NOTES["l43"]={"Lỗi: quên delete khi return sớm": "Lần gọi thứ hai đi vào nhánh return -1 nên bỏ qua delete[] a. Chạy hết: cột Heap còn một khối chưa được trả, và phần Kết quả báo rò rỉ bộ nhớ. Hàm càng nhiều đường ra càng dễ sót.", "Ví dụ: lớp MangDong tự trả vùng nhớ": "Cùng thuật toán nhưng mảng nằm trong đối tượng a. Ở cả hai đường ra (return t và return -1), ~MangDong() đều tự chạy trước khi hàm kết thúc: chữ “Tra … o” in ra trước kết quả. Heap không còn khối nào bị bỏ quên.", "Ví dụ: thứ tự tạo và hủy": "c bị hủy ngay ở dấu } của khối trong. Cuối main, các biến còn lại bị hủy ngược thứ tự tạo: d, rồi b, rồi a.", "Lỗi: chép nông, giải phóng hai lần": "b = a chép con trỏ p, không chép mảng: a.p và b.p trỏ cùng một khối heap (Bộ nhớ vẽ hai mũi tên tới một khối), nên sửa b làm a đổi theo (in 9). Cuối main, ~MangDong() của b trả khối đó, rồi ~MangDong() của a trả lại lần nữa: double free, chương trình dừng.", "Ví dụ: quy tắc ba, chép sâu": "Hàm tạo sao chép cấp mảng MỚI cho b rồi chép từng phần tử; toán tử gán trả mảng cũ của c, cấp mảng mới, chép. Ba đối tượng có ba khối heap riêng nên sửa cái này không ảnh hưởng cái khác (5 9 7), và cuối main mỗi khối được trả đúng một lần. this != &o phòng trường hợp gán cho chính nó (a = a).", "Ví dụ: cấm chép, truyền tham chiếu": "= delete xóa hẳn hai hàm chép: không ai chép được MangDong nữa, nên không bao giờ có hai đối tượng cùng giữ một mảng. Hàm cần dùng mảng thì nhận tham chiếu MangDong& (không chép gì).", "Lỗi: chép một đối tượng đã cấm chép": "Truyền theo giá trị nghĩa là chép a vào tham số m, mà hàm chép đã bị xóa: lỗi biên dịch ngay. Đó chính là điều ta muốn: lỗi chép nông bị chặn từ lúc biên dịch thay vì làm chương trình dừng khi chạy. Sửa: void inCo(const MangDong& m)."};EX_HINTS["l43"]=[["Hàm hủy viết ~MangDong() { delete[] p; } (new[] đi với delete[]).", "Chạy xong, xem cột Heap: khối đã được trả (“đã delete”)."], ["Hàm tạo sao chép: lấy n của o, cấp mảng mới, chép từng phần tử.", "Toán tử gán: kiểm tra this != &o, trả mảng cũ (delete[] p), cấp mảng mới, chép; cuối cùng return *this."], ["Giữ con trỏ a, dung lượng cap và số phần tử n.", "NganXep(const NganXep&) = delete; và NganXep& operator=(const NganXep&) = delete;"]];
/* ===================== BÀI 43 · RAII ===================== */
/* Bài 43 · RAII
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P43=[{label:"Lỗi: quên delete khi return sớm",input:"",code:"#include <iostream>\nusing namespace std;\n\nint tongBinhPhuong(int n) {\n    int* a = new int[n];\n    for (int i = 0; i < n; i++) {\n        a[i] = (i + 1) * (i + 1);\n    }\n    if (a[n - 1] > 50) {\n        cout << \"Qua lon\\n\";\n        return -1;\n    }\n    int t = 0;\n    for (int i = 0; i < n; i++) t += a[i];\n    delete[] a;\n    return t;\n}\nint main() {\n    cout << tongBinhPhuong(3) << \"\\n\";\n    cout << tongBinhPhuong(9) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: lớp MangDong tự trả vùng nhớ",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) {\n        p = new int[n];\n        cout << \"Cap \" << n << \" o\\n\";\n    }\n    ~MangDong() {\n        delete[] p;\n        cout << \"Tra \" << n << \" o\\n\";\n    }\n    int& operator[](int i) { return p[i]; }\n};\nint tongBinhPhuong(int n) {\n    MangDong a(n);\n    for (int i = 0; i < n; i++) {\n        a[i] = (i + 1) * (i + 1);\n    }\n    if (a[n - 1] > 50) {\n        cout << \"Qua lon\\n\";\n        return -1;\n    }\n    int t = 0;\n    for (int i = 0; i < n; i++) t += a[i];\n    return t;\n}\nint main() {\n    cout << tongBinhPhuong(3) << \"\\n\";\n    cout << tongBinhPhuong(9) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: thứ tự tạo và hủy",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass NhatKy {\n    string ten;\npublic:\n    NhatKy(string t) : ten(t) { cout << \"Tao \" << ten << \"\\n\"; }\n    ~NhatKy() { cout << \"Huy \" << ten << \"\\n\"; }\n};\nint main() {\n    NhatKy a(\"a\");\n    NhatKy b(\"b\");\n    {\n        NhatKy c(\"c\");\n        cout << \"Cuoi khoi trong\\n\";\n    }\n    NhatKy d(\"d\");\n    cout << \"Cuoi main\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: chép nông, giải phóng hai lần",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\npublic:\n    MangDong(int n) { p = new int[n]; }\n    ~MangDong() { delete[] p; }\n    void dat(int i, int x) { p[i] = x; }\n    int lay(int i) { return p[i]; }\n};\nint main() {\n    MangDong a(3);\n    a.dat(0, 5);\n    MangDong b = a;\n    b.dat(0, 9);\n    cout << a.lay(0) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: quy tắc ba, chép sâu",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) {\n        p = new int[n];\n        for (int i = 0; i < n; i++) p[i] = 0;\n    }\n    MangDong(const MangDong& o) : n(o.n) {\n        p = new int[n];\n        for (int i = 0; i < n; i++) p[i] = o.p[i];\n    }\n    MangDong& operator=(const MangDong& o) {\n        if (this != &o) {\n            delete[] p;\n            n = o.n;\n            p = new int[n];\n            for (int i = 0; i < n; i++) p[i] = o.p[i];\n        }\n        return *this;\n    }\n    ~MangDong() { delete[] p; }\n    int& operator[](int i) { return p[i]; }\n};\nint main() {\n    MangDong a(3);\n    a[0] = 5;\n    MangDong b = a;\n    b[0] = 9;\n    MangDong c(1);\n    c = a;\n    c[0] = 7;\n    cout << a[0] << \" \" << b[0] << \" \" << c[0] << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: cấm chép, truyền tham chiếu",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) { p = new int[n]; }\n    MangDong(const MangDong&) = delete;\n    MangDong& operator=(const MangDong&) = delete;\n    ~MangDong() { delete[] p; }\n    int size() const { return n; }\n    int& operator[](int i) { return p[i]; }\n};\nvoid dienSo(MangDong& m) {\n    for (int i = 0; i < m.size(); i++) m[i] = i * 10;\n}\nint main() {\n    MangDong a(4);\n    dienSo(a);\n    cout << a[3] << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: chép một đối tượng đã cấm chép",input:"",code:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) { p = new int[n]; }\n    MangDong(const MangDong&) = delete;\n    MangDong& operator=(const MangDong&) = delete;\n    ~MangDong() { delete[] p; }\n    int size() const { return n; }\n};\nvoid inCo(MangDong m) {\n    cout << m.size() << \"\\n\";\n}\nint main() {\n    MangDong a(4);\n    inCo(a);\n    return 0;\n}"}];
const sim43=makeSim2(document.getElementById("sim-l43"),{id:"s43",presets:P43});
makeEx2(document.getElementById("ex-l43"),sim43,[{t:"Mảng động tự giải phóng",d:"Hoàn thành lớp <code>MangDong<\/code>: hàm tạo nhận n, cấp <code>new int[n]<\/code>; hàm hủy trả bằng <code>delete[]<\/code>; <code>dat(i, x)<\/code>, <code>lay(i)<\/code>, <code>size()<\/code>. Chương trình đọc n rồi n số vào mảng, in tổng và số lớn nhất trên một dòng.",tests:[{in:"4\n3 9 -2 5",out:"15 9"},{in:"1\n-7",out:"-7 -7"},{in:"3\n0 0 0",out:"0 0"}],start:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) {\n        // cấp vùng nhớ\n    }\n    // hàm hủy\n    void dat(int i, int x) { }\n    int lay(int i) { return 0; }\n    int size() const { return n; }\n};\nint main() {\n    int n;\n    cin >> n;\n    MangDong a(n);\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        a.dat(i, x);\n    }\n    int tong = 0, lon = a.lay(0);\n    for (int i = 0; i < a.size(); i++) {\n        tong += a.lay(i);\n        if (a.lay(i) > lon) lon = a.lay(i);\n    }\n    cout << tong << \" \" << lon << \"\\n\";\n    return 0;\n}",need:/new\s+int\s*\[[\s\S]*~\s*MangDong\s*\(\s*\)\s*\{[^}]*delete\s*\[\s*\]/,needMsg:"Hãy cấp bằng new int[n] trong hàm tạo và trả bằng delete[] trong hàm hủy ~MangDong()."},{t:"Chép sâu",d:"Lớp <code>MangDong<\/code> đã có hàm tạo và hàm hủy nhưng chưa có hàm tạo sao chép và toán tử gán, nên chương trình bên dưới chép nông và dừng vì giải phóng hai lần. Hãy viết hai hàm đó (chép sâu) để a, b, c độc lập. Chương trình đọc n và n số, rồi in ba dòng: các phần tử của a, b, c.",tests:[{in:"3\n1 2 3",out:"1 2 3\n100 2 3\n1 2 300"},{in:"1\n5",out:"5\n100\n300"}],start:"#include <iostream>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : n(n) { p = new int[n]; }\n    // MangDong(const MangDong& o) ...\n    // MangDong& operator=(const MangDong& o) ...\n    ~MangDong() { delete[] p; }\n    int size() const { return n; }\n    int& operator[](int i) { return p[i]; }\n};\nvoid in(MangDong& m) {\n    for (int i = 0; i < m.size(); i++) cout << m[i] << \" \";\n    cout << \"\\n\";\n}\nint main() {\n    int n;\n    cin >> n;\n    MangDong a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    MangDong b = a;\n    b[0] = 100;\n    MangDong c(1);\n    c = a;\n    c[n - 1] = 300;\n    in(a);\n    in(b);\n    in(c);\n    return 0;\n}",need:/MangDong\s*\(\s*const\s+MangDong\s*&[\s\S]*operator\s*=\s*\(\s*const\s+MangDong\s*&/,needMsg:"Hãy viết hàm tạo sao chép MangDong(const MangDong& o) và toán tử gán operator=(const MangDong& o)."},{t:"Ngăn xếp dung lượng cố định",d:"Viết lớp <code>NganXep<\/code> giữ tối đa c số nguyên trong một mảng cấp bằng <code>new<\/code>: hàm tạo nhận c, hàm hủy trả mảng, <b>cấm chép<\/b> bằng <code>= delete<\/code>. Nhập c, q rồi q lệnh: <code>push x<\/code> (đầy thì in <code>Day<\/code>), <code>pop<\/code> (in phần tử ở đỉnh rồi bỏ nó; rỗng thì in <code>Rong<\/code>). Cuối cùng in <code>Con: k<\/code>.",tests:[{in:"2 5\npush 1\npush 2\npush 3\npop\npop",out:"Day\n2\n1\nCon: 0"},{in:"1 2\npop\npush 7",out:"Rong\nCon: 1"},{in:"3 4\npush 4\npush 5\npop\npush 6",out:"5\nCon: 2"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass NganXep {\n    // int* a; int cap, n;\npublic:\n    // NganXep(int c), ~NganXep(), cấm chép\n    // bool day() const, bool rong() const, void push(int x), int top() const, void pop(), int size() const\n};\nint main() {\n    int c, q;\n    cin >> c >> q;\n    // NganXep s(c);\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n    }\n    return 0;\n}",need:/=\s*delete[\s\S]*~\s*NganXep|~\s*NganXep[\s\S]*=\s*delete/,needMsg:"Hãy viết hàm hủy ~NganXep() và cấm chép bằng = delete."}]);

makeQuiz("quiz43","score43",[{"q": "RAII bảo đảm điều gì?", "o": ["Không bao giờ hết bộ nhớ", "Tài nguyên được trả trong hàm hủy, và hàm hủy luôn chạy khi đối tượng hết phạm vi, kể cả khi return sớm", "Chương trình chạy nhanh hơn", "Không cần hàm tạo"], "a": 1, "e": "Đối tượng cục bộ luôn bị hủy khi ra khỏi phạm vi, bằng bất kỳ đường nào; hàm hủy là nơi trả tài nguyên."}, {"q": "Trong main tạo lần lượt <code>A x; B y; C z;<\/code>. Cuối main, hàm hủy chạy theo thứ tự:", "o": ["x, y, z", "z, y, x", "Không xác định", "Chỉ z"], "a": 1, "e": "Hủy ngược thứ tự tạo."}, {"q": "Lớp chỉ có <code>int* p<\/code> (cấp bằng new trong hàm tạo, delete trong hàm hủy), không có hàm chép. <code>MangDong b = a;<\/code> gây ra:", "o": ["b có mảng riêng", "a và b trỏ cùng một mảng, cuối chương trình mảng bị delete hai lần", "Lỗi biên dịch", "Không có gì đặc biệt"], "a": 1, "e": "Chép mặc định chỉ chép con trỏ (chép nông). Cần quy tắc ba hoặc = delete."}, {"q": "Viết <code>MangDong(const MangDong&amp;) = delete;<\/code> trong lớp có tác dụng gì?", "o": ["Xóa mọi đối tượng MangDong", "Cấm chép: mọi chỗ chép MangDong (khởi tạo bằng bản khác, truyền theo giá trị) thành lỗi biên dịch", "Chép sâu tự động", "Gọi hàm hủy sớm"], "a": 1, "e": "Hàm bị xóa không gọi được; trình biên dịch báo use of deleted function ở chỗ cố chép."}]);

